import { Position } from "../../../core/position.js";
import { Range } from "../../../core/range.js";
import { BaseToken } from "../../baseToken.js";
import type { Line } from "../../linesCodec/tokens/line.js";

/**
 * A token that represent a `!` with a `range`. The `range`
 * value reflects the position of the token in the original data.
 */
export class ExclamationMark extends BaseToken {
	/**
	 * The underlying symbol of the token.
	 */
	public static readonly symbol: string = "!";

	/**
	 * Return text representation of the token.
	 */
	public get text(): string {
		return ExclamationMark.symbol;
	}

	/**
	 * Create new token with range inside
	 * the given `Line` at the given `column number`.
	 */
	public static newOnLine(
		line: Line,
		atColumnNumber: number,
	): ExclamationMark {
		const { range } = line;

		const startPosition = new Position(
			range.startLineNumber,
			atColumnNumber,
		);
		const endPosition = new Position(
			range.startLineNumber,
			atColumnNumber + ExclamationMark.symbol.length,
		);

		return new ExclamationMark(
			Range.fromPositions(startPosition, endPosition),
		);
	}

	/**
	 * Returns a string representation of the token.
	 */
	public override toString(): string {
		return `exclamation-mark${this.range}`;
	}
}
